const {add,mul,number}=require('./autonomous-economy.cjs');
const agriculturalKeys=['potentialLand','cultivatedLand','usedLand','idleLand','agriculturalWorkers','agriculturalProduced','agriculturalOutputPerLandBps','agriculturalOutputPerWorkerBps','agriculturalSalesIncome','agriculturalCogs','grainSold','flourSold','foodSold','grainSurplus','flourSurplus','foodSurplus','ruralFoodNeed','urbanFoodNeed','ruralNaturalFood','ruralPaidFood','urbanPaidFood','ruralFoodUnmet','urbanFoodUnmet','ruralFoodSpending','urbanFoodSpending','internalFoodQuantity','internalFoodPayment','ruralIncome','urbanIncome','ruralFoodUnaffordable','urbanFoodUnaffordable','ruralFoodRationed','urbanFoodRationed','householdExportQuantity','householdExportIncome','enterpriseExportQuantity','deliveredEquipment','householdInventoryValue','cargoBookValue'];
