  for(const row of rows){result.householdInventoryValue=add(result.householdInventoryValue,row.inventories.reduce((n,s)=>add(n,s.bookValueMinor),0));result.householdExportQuantity=add(result.householdExportQuantity,row.exports?.quantity||0);result.householdExportIncome=add(result.householdExportIncome,row.exports?.payments||0);const food=row.ledger.find(b=>b.goodId===e.rules.foodGoodId);result.naturalFoodProduced=add(result.naturalFoodProduced,food.produced);result.naturalFoodConsumed=add(result.naturalFoodConsumed,food.consumed);result.householdWorkers=add(result.householdWorkers,row.workers);const sales=row.revenue-(row.sectors?.internalPayment||0);result.householdSalesIncome=add(result.householdSalesIncome,sales);income.set(row.householdId,add(income.get(row.householdId),sales));result.agriculturalSalesIncome=add(result.agriculturalSalesIncome,sales);result.agriculturalCogs=add(result.agriculturalCogs,(row.cogs||0)-(row.sectors?.internalCogs||0));const reserved=require('./agricultural-resources.cjs').reserves(e,row);for(const good of ['grain','flour','food']){const b=row.ledger.find(b=>b.goodId===good),stock=row.inventories.find(s=>s.goodId===good);if(b)result[good+'Sold']=add(result[good+'Sold'],b.sold);if(stock)result[good+'Surplus']=add(result[good+'Surplus'],Math.max(0,stock.quantity-(reserved.get(good)||0)));}if(row.sectors){const v=row.sectors;for(const [key,source]of [['ruralFoodNeed','ruralNeed'],['urbanFoodNeed','urbanNeed'],['ruralNaturalFood','ruralNatural'],['ruralPaidFood','ruralPaid'],['urbanPaidFood','urbanPaid'],['ruralFoodSpending','ruralSpending'],['urbanFoodSpending','urbanSpending'],['internalFoodQuantity','internalQuantity'],['internalFoodPayment','internalPayment']])result[key]=add(result[key],v[source]);result.ruralFoodUnmet=add(result.ruralFoodUnmet,v.ruralNeed-v.ruralNatural-v.ruralPaid);result.urbanFoodUnmet=add(result.urbanFoodUnmet,v.urbanNeed-v.urbanPaid);result.ruralFoodUnaffordable=add(result.ruralFoodUnaffordable,v.ruralNeed-v.ruralAffordable);result.urbanFoodUnaffordable=add(result.urbanFoodUnaffordable,v.urbanNeed-v.urbanAffordable);result.ruralFoodRationed=add(result.ruralFoodRationed,v.ruralAffordable-v.ruralNatural-v.ruralPaid);result.urbanFoodRationed=add(result.urbanFoodRationed,v.urbanAffordable-v.urbanPaid);const h=houses.find(h=>h.id===row.householdId),pooled=add(h.stats.wages,h.stats.payout),ruralIncome=number(BigInt(pooled)*BigInt(v.ruralPopulation)/BigInt(Math.max(1,add(v.ruralPopulation,v.urbanPopulation))));result.ruralIncome=add(result.ruralIncome,add(ruralIncome,sales));result.urbanIncome=add(result.urbanIncome,pooled-ruralIncome);}}
  const foodNeeds=new Set(e.rules.consumerNeeds?.filter(n=>n.goodId===e.rules.foodGoodId&&n.usage==='consumable').map(n=>n.id)||[]);
  for(const h of houses){result.ownerIncome=add(result.ownerIncome,h.stats.payout);result.householdIncome=add(result.householdIncome,income.get(h.id));if(!income.get(h.id))result.noIncomeHouseholds++;if(!e.rules.consumerNeeds)result.marketFoodConsumed=add(result.marketFoodConsumed,h.stats.purchased);for(const n of h.consumerState||[])if(foodNeeds.has(n.needId))result.marketFoodConsumed=add(result.marketFoodConsumed,n.stats.purchased);}
  result.marketFoodConsumed-=result.naturalFoodConsumed;
  for(const c of e.trade?.routing?.cargo||[]){const actor=actors.get(c.ownerId);if(!provinceIds||provinceIds.has(actor.provinceId)){result.cargoQuantity=add(result.cargoQuantity,c.quantity);result.cargoBookValue=add(result.cargoBookValue,c.bookValueMinor);result.transportEscrow=add(result.transportEscrow,c.escrowMinor);}}
  for(const f of firms){const c=controllers.get(f.id);if(c){result.investmentsPlanned=add(result.investmentsPlanned,c.pendingCapacity);result.investmentsCompletedValue=add(result.investmentsCompletedValue,number(BigInt(c.investment)>0n?BigInt(c.investment):0n));}}
  result.deliveredEquipment=Object.entries(e.trade?.routing?.month.equipmentReceipts||{}).filter(([id])=>!provinceIds||provinceIds.has(id)).reduce((n,[,q])=>add(n,q),0);for(const flow of e.trade?.flows||[])if(actors.get(flow.sellerEnterpriseId)?.recipeId&&(!provinceIds||provinceIds.has(flow.sellerProvinceId)))result.enterpriseExportQuantity=add(result.enterpriseExportQuantity,flow.quantity);for(const cargo of e.trade?.routing?.cargo||[])if(cargo.id>=e.trade.routing.nextId-e.trade.routing.month.started&&actors.get(cargo.sellerId)?.recipeId&&(!provinceIds||provinceIds.has(actors.get(cargo.sellerId).provinceId)))result.enterpriseExportQuantity=add(result.enterpriseExportQuantity,cargo.quantity);
  const land=(e.agriculture?.rows||[]).filter(r=>!provinceIds||provinceIds.has(r.provinceId)),methods=new Set((e.agriculture?.methods||[]).map(m=>m.recipeId));for(const r of land)for(const k of ['potentialLand','cultivatedLand','usedLand'])result[k]=add(result[k],r[k]);result.idleLand=result.cultivatedLand-result.usedLand;for(const f of firms)if(methods.has(f.recipeId)){result.agriculturalProduced=add(result.agriculturalProduced,mul(f.stats.batches,recipes.get(f.recipeId).output.quantity));result.agriculturalWorkers=add(result.agriculturalWorkers,f.stats.workers);}for(const row of rows)for(const stage of row.stages)if(methods.has(stage.recipeId)){const recipe=recipes.get(stage.recipeId),q=row.ledger.find(b=>b.goodId===recipe.output.goodId).produced;result.agriculturalProduced=add(result.agriculturalProduced,q);result.agriculturalWorkers=add(result.agriculturalWorkers,mul(q/recipe.output.quantity,recipe.workersPerBatch));}result.agriculturalOutputPerLandBps=result.usedLand?number(BigInt(result.agriculturalProduced)*10000n/BigInt(result.usedLand)):0;result.agriculturalOutputPerWorkerBps=result.agriculturalWorkers?number(BigInt(result.agriculturalProduced)*10000n/BigInt(result.agriculturalWorkers)):0;
  return result;
